/* 农民选点：优先最近的己方矿，否则最近的非己方矿（去占点）。 */
function pickSiteFor(x, y, resSites) {
  var bestOwn = null;
  var bestOwnD = 9999;
  var bestAny = null;
  var bestAnyD = 9999;
  for (var i = 0; i < resSites.length; i++) {
    var s = resSites[i];
