/* ---------- 小工具（纯整数） ---------- */
function cellKey(x, y) {
  return x + ',' + y;
}

function cheb(ax, ay, bx, by) {
  var dx = ax - bx;
  var dy = ay - by;
  if (dx < 0) dx = -dx;
  if (dy < 0) dy = -dy;
  return dx > dy ? dx : dy;
}

