  var sy = dy > 0 ? 1 : (dy < 0 ? -1 : 0);
  var cx, cy;
  if (sx !== 0 && sy !== 0) {
    cx = ux + sx; cy = uy + sy;
    if (walkable(cx, cy) && isFree(cx, cy, occ)) return [cx, cy];
  }
  if (sx !== 0) {
    cx = ux + sx; cy = uy;
    if (walkable(cx, cy) && isFree(cx, cy, occ)) return [cx, cy];
  }
  if (sy !== 0) {
    cx = ux; cy = uy + sy;
    if (walkable(cx, cy) && isFree(cx, cy, occ)) return [cx, cy];
