  probeConfirm = 0;
  probePhase = 0;
  probeUnitId = -1;
  if (probeIndex > 3) {
    probeIndex = 0;
    probeRounds++;
    if (probeRounds >= PROBE_MAX_ROUNDS) {
      MY_INDEX = 0;
      selfState = SELF_KNOWN;
      selfFallback = true;
    }
