/* 认错时的自愈：退回未认状态重新探测。 */
function resetSelf() {
  if (selfState === SELF_UNKNOWN) return;
  selfState = SELF_UNKNOWN;
  MY_INDEX = -1;
  probeIndex = 0;
  probeRounds = 0;
  probeTries = 0;
  probeConfirm = 0;
  probePhase = 0;
  probeUnitId = -1;
  selfFallback = false;
