  probeAdvance();                                    /* 挪去了别处：不是我的单位 */
}

/* 未认出自己的那几 tick：只发一条探测 intent，不发其它 intent。 */
function runProbe() {
  var occ = new Map();
  var all = getObjectsByType('unit');
  for (var i = 0; i < all.length; i++) occ.set(cellKey(all[i].x, all[i].y), all[i].id);
  if (probePhase === 1) probeObserve();
  else probeIssue(occ);
}

/* 动作回执里的属主错 = 认错了人，自愈重认。 */
